package ociresources

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/imageupdate"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/registryalias"
	"github.com/anthnel/devdesk/internal/ui/sigcol"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/anthnel/devdesk/internal/ui/updatecol"
)

// imageRow is one line of the Images tab: the image, plus everything the row
// says about it that does not live on the image — the cached scan counts,
// whether a scan is running or the last one failed, and the alias-substituted
// name.
//
// The columns are built once, in New, so their Cell functions cannot reach back
// into the model for any of that. Carrying it on the row instead is what keeps
// the sort honest: the C column orders by the same number it prints, where the
// old comparator looked the entry up a second time.
type imageRow struct {
	Image       docker.Image
	DisplayName string
	RawName     string
	Entry       cache.ImageScanEntry
	Scanned     bool
	Scanning    bool
	Failed      bool
	// Pulling is true for the duration of a docker pull, whether the image
	// was already local (an existing row spins) or not (a placeholder row is
	// synthesized — Image stays zero-valued until fetchImages() replaces it).
	Pulling      bool
	SpinnerFrame string
	// Update is whether a newer image exists in its registry (§3.88).
	Update imageupdate.Status
	// Signature is what the signature check found on the local digest (§3.82).
	Signature sigcol.State
}

// The columns something else refers to. imageColumnID is where a running action
// puts its spinner; imageColumnName is what the tab opens sorted by.
const (
	imageColumnID   = 0
	imageColumnName = 1
)

// secretsColumnWidth is the Secrets column, at the width the workspaces list
// gives it. It does not sort, same as there: `datatable` reserves two extra
// cells for a sortable column's arrow, which is expensive for a glyph.
const secretsColumnWidth = 7

// misconfigColumnWidth is five cells: "CFG" costs three and a sortable header
// asks for width(Title)+2, while the value costs four at worst — three digits
// and the "?" that says the count is partial.
const misconfigColumnWidth = 5

// secrets is the row's verdict — unknown as long as the image has not been
// scanned, and also unknown for a scan that had no secrets stage.
func (r imageRow) secrets() theme.SecretsState {
	return theme.SecretsVerdict(r.Entry.Sensitive, r.Scanned)
}

// misconfig is the row's misconfiguration verdict, computed the way the
// workspaces list and the security inventory compute theirs.
//
// An image has misconfigurations to find: `trivy image --scanners misconfig`
// reads the Dockerfile instructions baked into the layers, which is why this
// column is not repository-only the way the CI grade is.
func (r imageRow) misconfig() theme.MisconfigState {
	return theme.MisconfigVerdict(r.Entry.Misconfig != nil, r.Scanned, r.Entry.Misconfig.Total())
}

// misconfigColumn is the misconfiguration count. It exists only when
// scan.categories.misconfig is on — off, it would be a dash on every row — and
// it sits after the four CVE counters, before Scanned, which is where the
// workspaces list and the security inventory put theirs.
func misconfigColumn() datatable.Column[imageRow] {
	return datatable.Column[imageRow]{
		Title: "CFG", Sizing: datatable.SizingFixed, MinWidth: misconfigColumnWidth,
		Cell: func(r imageRow) string {
			return theme.MisconfigCell(r.misconfig(), r.Entry.Misconfig.Total(), r.Entry.Misconfig.UnrenderedCount() > 0)
		},
		Style: func(r imageRow) lipgloss.Style {
			return theme.MisconfigStyle(r.misconfig(), r.Entry.Misconfig.WorstSeverity())
		},
		Less: func(a, b imageRow) bool { return a.Entry.Misconfig.Total() < b.Entry.Misconfig.Total() },
	}
}

// cveColumn builds one of the four severity count columns.
//
// severity names the column's level for the colour, spelled as the scanners
// spell it — the title here is a single letter, which is no basis for deciding
// what colour a count is.
func cveColumn(title, severity string, get func(cache.ImageScanEntry) int) datatable.Column[imageRow] {
	return datatable.Column[imageRow]{
		Title: title, Sizing: datatable.SizingFixed, MinWidth: 4,
		Cell: func(r imageRow) string { return formatCVECount(get(r.Entry), r.Scanned) },
		// A zero is dim, like an unscanned image: four coloured zeroes on a
		// clean image would read as four findings.
		Style: func(r imageRow) lipgloss.Style {
			if !r.Scanned || get(r.Entry) == 0 {
				return theme.DimStyle
			}
			return theme.SeverityTextStyle(severity)
		},
		Less: func(a, b imageRow) bool { return get(a.Entry) < get(b.Entry) },
	}
}

// scannedStyle colours the scan state, a failure being the one value in the
// column that asks for anything.
func scannedStyle(r imageRow) lipgloss.Style {
	switch {
	case r.Failed:
		return theme.StatusErrorStyle
	case r.Scanning, !r.Scanned:
		return theme.DimStyle
	}
	// No opinion here: the table sets the theme's text color.
	return lipgloss.NewStyle()
}

// scannedCell reports the scan state: the spinner while one runs, an error icon
// when the last attempt failed, otherwise how long ago it succeeded.
func scannedCell(r imageRow) string {
	switch {
	case r.Scanning:
		return r.SpinnerFrame + "scanning"
	case r.Failed:
		return theme.IconError + " error"
		cveColumn("L", "LOW", func(e cache.ImageScanEntry) int { return e.Low }),
	}
	if withMisconfig {
		cols = append(cols, misconfigColumn())
	}
	return append(cols, datatable.Column[imageRow]{
		Title: "Scanned", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 14,
		Cell:  scannedCell,
		Style: scannedStyle,
		Less:  func(a, b imageRow) bool { return a.Entry.ScannedAt.Before(b.Entry.ScannedAt) },
	})
}

// imageRows decorates the image list with the scan state the table shows,
// plus a placeholder row for any pull in flight whose image is not local yet.
func (m *Model) imageRows() []imageRow {
	aliases := registryalias.From(m.registries)
	// The scan frame comes from the registry, which holds the one chain that
	// animates work (D5). spinnerFrameIdx below is local, and it animates
	// loading — a load is not a job.
	frame := m.jobFrame
	scanning := m.scanningNames()
	pulling := m.pullingNames()

	seen := make(map[string]bool, len(m.images))
	rows := make([]imageRow, 0, len(m.images))
	for _, img := range m.images {
		raw := img.Name()
		seen[raw] = true
		entry, scanned := m.scanCache[raw]
		rows = append(rows, imageRow{
			Image:        img,
			DisplayName:  docker.ApplyAliases(raw, aliases),
			RawName:      raw,
			Entry:        entry,
			Scanned:      scanned,
			Scanning:     scanning[raw],
			Failed:       m.failedScans[raw],
			Pulling:      pulling[raw],
			SpinnerFrame: frame,
			Update:       m.imageUpdate(img),
			Signature:    m.imageSignature(img),
		})
	}
	// An image pulled for the first time has no local row to spin yet — this
	// is the common case when pulling from the registry browser, so it gets
	// a placeholder rather than staying invisible until the pull completes.
	for name := range pulling {
		if seen[name] {
			continue
		}
		rows = append(rows, imageRow{
			DisplayName:  docker.ApplyAliases(name, aliases),
			RawName:      name,
			Pulling:      true,
			SpinnerFrame: frame,
		})
	}
	return rows
}

// imageUpdate is the Update cell of an image (§3.88). An untagged image names
// nothing to ask about; one without a registry digest was built or loaded here,
// and is never sent to a registry (pulledImageRefs).
func (m *Model) imageUpdate(img docker.Image) imageupdate.Status {
	switch {
	case img.Tag == "" || img.Tag == "<none>":
		return imageupdate.Status{}
	case len(img.RepoDigests) == 0:
		return imageupdate.Status{Kind: imageupdate.LocalBuild}
	}
	return m.updates.Status(img.Name(), img.RepoDigests, imageupdate.LocalBuild)
}

// formatBytes formats bytes into human-readable string
func formatBytes(b int64) string {
	switch {
	case b >= 1e9:
		return fmt.Sprintf("%.1f GB", float64(b)/1e9)
	case b >= 1e6:
		return fmt.Sprintf("%.1f MB", float64(b)/1e6)
	case b >= 1e3:
		return fmt.Sprintf("%.1f kB", float64(b)/1e3)
	default:
		return fmt.Sprintf("%d B", b)
	}
}

// formatCVECount formats a CVE count for display, returns "-" if not scanned
func formatCVECount(count int, scanned bool) string {
	if !scanned {
		return "-"
	}
	return fmt.Sprintf("%d", count)
}

// updateImageTable rebuilds the image table rows.
//
// Every caller reaches here after changing something the row shows — a scan
// started, finished, or the list came back — so the decoration is recomputed
// wholesale rather than patched in place.
func (m *Model) updateImageTable() {
	m.imageTable.SetItems(m.imageRows())
	m.imageTable.SetHeight(m.tableHeight())
}

// networkColumnID and volumeColumnDriver are where a running action puts its
// spinner — the cell each table can spare while one row is being removed.
const (
	networkColumnID    = 0
	volumeColumnDriver = 1
)

// networkColumns describes the Networks tab. Neither this table nor the volumes
// one sorts or filters today, so no Less and no Search: `/` and `.` stay inert
// rather than being wired to a bar this view's footer does not render.
func networkColumns() []datatable.Column[docker.Network] {
	return []datatable.Column[docker.Network]{
		{Title: "ID", Sizing: datatable.SizingFixed, MinWidth: 14, Cell: func(n docker.Network) string { return shortID(n.ID) }},
		{Title: "Name", Sizing: datatable.SizingContent, MinWidth: 20, Flex: 1, Cell: func(n docker.Network) string { return n.Name }},
		{Title: "Driver", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12, Cell: func(n docker.Network) string { return n.Driver }},
//
// The view's own `spinner.Model` stays, and deliberately: it animates *loading*
// — the image list, the networks, a `docker` action on a row — and a load is not
// a job. What moved is the frame the scan cells use, which now comes from the
// one chain the router holds (D5).

// handleJobsChanged takes the router's snapshot. It is the only writer of the
// two fields.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.failures = slices.Clone(msg.Failures)
	m.contextName = msg.Context
	// The footer's spinner is deliberately not touched: here it belongs to
	// *loading* — a tab reading its list — and this view's scan progress is on
	// the rows, not in the footer. Two writers of one field would fight every
	// frame a scan and a load overlapped.
	m.updateImageTable()
	if m.registryBrowser != nil {
		m.registryBrowser.SetTagScanningSet(m.scanningNames())
	}
	return m, nil
}

// handleFrameMsg takes the animation's frame for the scan cells. The footer is
// untouched, for the reason handleJobsChanged gives.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.jobFrame = msg.Frame
	m.updateImageTable()
	return m, nil
}

// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
func (m Model) scanRun(names []string) jobs.Run {
	run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
	// The alias is applied here rather than by whoever shows the run: it is
	// this view's configuration that defines it, and `:jobs` has no business
	// reading a registry list to print a name.
	aliases := registryalias.From(m.registries)
	for _, name := range names {
		if display := docker.ApplyAliases(name, aliases); display != name {
			run = run.WithDisplay(name, display)
		}
	}
	return run
}

// scanningImage reports whether an image is queued or being scanned, whoever
// started it.
func (m Model) scanningImage(name string) bool {
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindScan {
			continue
		}
		for _, item := range run.Items {
			if item.Target == name && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}
