// imageUpdate is the Update cell of an image (§3.88). An untagged image names
// nothing to ask about; one without a registry digest was built or loaded here,
// and is never sent to a registry (pulledImageRefs).
func (m *Model) imageUpdate(img docker.Image) imageupdate.Status {
	switch {
	case img.Tag == "" || img.Tag == "<none>":
		return imageupdate.Status{}
	case len(img.RepoDigests) == 0:
		return imageupdate.Status{Kind: imageupdate.LocalBuild}
	}
	return m.updates.Status(img.Name(), img.RepoDigests, imageupdate.LocalBuild)
}

// formatBytes formats bytes into human-readable string
func formatBytes(b int64) string {
	switch {
	case b >= 1e9:
		return fmt.Sprintf("%.1f GB", float64(b)/1e9)
	case b >= 1e6:
		return fmt.Sprintf("%.1f MB", float64(b)/1e6)
	case b >= 1e3:
		return fmt.Sprintf("%.1f kB", float64(b)/1e3)
	default:
		return fmt.Sprintf("%d B", b)
	}
}

// formatCVECount formats a CVE count for display, returns "-" if not scanned
func formatCVECount(count int, scanned bool) string {
	if !scanned {
		return "-"
	}
	return fmt.Sprintf("%d", count)
}

// updateImageTable rebuilds the image table rows.
//
// Every caller reaches here after changing something the row shows — a scan
// started, finished, or the list came back — so the decoration is recomputed
// wholesale rather than patched in place.
func (m *Model) updateImageTable() {
	m.imageTable.SetItems(m.imageRows())
	m.imageTable.SetHeight(m.tableHeight())
}

// networkColumnID and volumeColumnDriver are where a running action puts its
// spinner — the cell each table can spare while one row is being removed.
const (
	networkColumnID    = 0
	volumeColumnDriver = 1
)

// networkColumns describes the Networks tab. Neither this table nor the volumes
// one sorts or filters today, so no Less and no Search: `/` and `.` stay inert
// rather than being wired to a bar this view's footer does not render.
func networkColumns() []datatable.Column[docker.Network] {
	return []datatable.Column[docker.Network]{
		{Title: "ID", Sizing: datatable.SizingFixed, MinWidth: 14, Cell: func(n docker.Network) string { return shortID(n.ID) }},
		{Title: "Name", Sizing: datatable.SizingContent, MinWidth: 20, Flex: 1, Cell: func(n docker.Network) string { return n.Name }},
		{Title: "Driver", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12, Cell: func(n docker.Network) string { return n.Driver }},
//
// The view's own `spinner.Model` stays, and deliberately: it animates *loading*
// — the image list, the networks, a `docker` action on a row — and a load is not
// a job. What moved is the frame the scan cells use, which now comes from the
// one chain the router holds (D5).

// handleJobsChanged takes the router's snapshot. It is the only writer of the
// two fields.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.failures = slices.Clone(msg.Failures)
	m.contextName = msg.Context
	// The footer's spinner is deliberately not touched: here it belongs to
	// *loading* — a tab reading its list — and this view's scan progress is on
	// the rows, not in the footer. Two writers of one field would fight every
	// frame a scan and a load overlapped.
	m.updateImageTable()
	if m.registryBrowser != nil {
		m.registryBrowser.SetTagScanningSet(m.scanningNames())
	}
	return m, nil
}

// handleFrameMsg takes the animation's frame for the scan cells. The footer is
// untouched, for the reason handleJobsChanged gives.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.jobFrame = msg.Frame
	m.updateImageTable()
	return m, nil
}

// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
func (m Model) scanRun(names []string) jobs.Run {
	run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
	// The alias is applied here rather than by whoever shows the run: it is
	// this view's configuration that defines it, and `:jobs` has no business
	// reading a registry list to print a name.
	aliases := registryalias.From(m.registries)
	for _, name := range names {
		if display := docker.ApplyAliases(name, aliases); display != name {
			run = run.WithDisplay(name, display)
		}
	}
	return run
}

